		def generate_match_score(home_rating, away_rating):
			"""
			Generates randomized football scores based on team ratings.
			Uses Poisson distribution for goal prediction with team strength adjustments.
			
			Args:
				home_rating (float): Rating of home team (0-100)
				away_rating (float): Rating of away team (0-100)
			
			Returns:
				tuple: (home_goals, away_goals)
			"""
			# 1. Calculate strength difference with home advantage
			home_advantage = 0.6  # Home teams typically have 0.3 goal advantage
			strength_diff = (home_rating - away_rating) / 100
			
			# 2. Calculate base goal expectations (Poisson lambda)
			# Base values calibrated for realistic score distributions
			if home_rating >= away_rating:
				base_home_xg = 1.2 + strength_diff + home_advantage
				base_away_xg = 1.2 - strength_diff
			else:
				base_home_xg = 1.2 + strength_diff
				base_away_xg = 1.2 - strength_diff+home_advantage
			
			# 3. Apply Poisson distribution for goal simulation
			g1 = 0
			g2 = 0
			L = math.exp(-base_home_xg)
			p = 1.0
			while p > L:
				g1 += 1
				p *= random.random()
			
			L = math.exp(-base_away_xg)
			p = 1.0
			while p > L:
				g2 += 1
				p *= random.random()
			
			# 4. Apply variance factors for realistic surprises
			# Underdog boost (up to 30% chance of extra goal)
			if home_rating < away_rating and random.random() < 0.3:
				g1 += 1
			elif away_rating < home_rating and random.random() < 0.3:
				g2 += 1
			
			# Clamp goals between 0-8 for realism
			return (
				max(0, min(g1, 8)),
				max(0, min(g2, 8))
			)
